{
  "a_sentences": [
    {
      "a_text": "Streitig ist die Höhe des Anspruchs des Versicherten auf Leistungen für Pflege und Hilfe zu Hause (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Empfehlungen Nr. 01/2022 greifen zu kurz, da sie die medizinische Pflege nach Art. 18 Abs. 1 UVV auf die in Art. 7 Abs. 2 lit. b KLV genannten Verrichtungen beschränken (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Trotz dieser Empfehlungen ist zu prüfen, ob die umstrittenen Pflegemassnahmen medizinische Pflege gemäss Art. 18 Abs. 1 UVV oder nichtmedizinische Hilfe gemäss Art. 18 Abs. 2 lit. b UVV darstellen (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Die Vorinstanz qualifizierte die Massnahmen zur Dekubitusprophylaxe, die Lagerung im Bett, das Tragen von Kompressionsstrümpfen und das Schneiden der Fingernägel als medizinische Pflege, weil sie der Vermeidung einer gesundheitlichen Verschlechterung dienen (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Die Suva wendet ein, die Lagerung diene lediglich der Positionierung und sei keine medizinische Pflegemassnahme; das Bundesgericht hält jedoch fest, eine fehlerhafte Lagerung könne einen Dekubitus verursachen (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Das Bundesgericht erachtet die Massnahmen als medizinisch indiziert, da sie ärztlich verordnet sind und einer ärztlichen Anordnung im weiten Sinn genügen (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Auch das Schneiden der Fingernägel wird als medizinisch indiziert beurteilt, weil es Hautverletzungen vorbeugen kann (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht weist die Beschwerde der SWICA ab und bestätigt die vorinstanzliche Zuordnung der Pflegemassnahmen zur medizinischen Pflege nach Art. 18 Abs. 1 UVV (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
